#
# Hook: SessionStart
# Purpose: Refresh the local policy cache from the control-plane.
#
# Runs after synaptory-skills-fetch.sh. Uses `synaptory config fetch --if-stale`
# so it only pulls a new payload when the server digest changed — cheap on
# repeat sessions. Network failure is non-fatal: the cached policy continues
# to apply.

set -euo pipefail

PLUGIN_ROOT="${PLUGIN_ROOT:-$(cd "$(dirname "$0")/.." && pwd)}"
# shellcheck source=./_plugin-env.sh
source "${PLUGIN_ROOT}/hooks/_plugin-env.sh"

cli=$("${PLUGIN_ROOT}/hooks/_resolve-cli.sh" 2>/dev/null || true)
if [[ -z "$cli" ]] || [[ ! -x "$cli" ]]; then
  exit 0
fi

"$cli" config fetch --if-stale 2>&1 || true
